from collections import deque

def diameter(root) -> int:               # longest path between two nodes, in edges
    def walk(node):                      # returns (height, best diameter) of the subtree
        if not node:
            return 0, 0
        (lh, lb), (rh, rb) = walk(node.left), walk(node.right)
        return 1 + max(lh, rh), max(lb, rb, lh + rh)   # a parent extends ONE side
    return walk(root)[1]

def level_order(root) -> list[list[int]]:
    levels, q = [], deque([root] if root else [])
    while q:
        levels.append([n.val for n in q])              # the queue holds one full level
        for _ in range(len(q)):                        # snapshot: only this level
            n = q.popleft()
            q.extend(c for c in (n.left, n.right) if c)
    return levels

def is_bst(node, lo=float("-inf"), hi=float("inf")) -> bool:
    if not node:
        return True
    ok = lo < node.val < hi              # bounds come from ALL ancestors, not the parent
    return ok and is_bst(node.left, lo, node.val) and is_bst(node.right, node.val, hi)

def lca(root, p, q):
    if root is None or root is p or root is q:
        return root
    left, right = lca(root.left, p, q), lca(root.right, p, q)
    return root if left and right else left or right   # both sides found: split point
